// NormalizeAds: Code node, "Run Once for All Items"
const out = [];

for (const item of $input.all()) {
  const a = item.json;
  const snap = a.snapshot || {};
  const cards = (snap.cards && snap.cards.length) ? snap.cards : (snap.videos || []);

  // har ad ka pehla video card
  const c = cards.find(x => x.videoHdUrl || x.videoSdUrl);
  if (!c) continue;

  const startMs = a.startDate ? a.startDate * 1000 : null;
  const endMs = a.endDate ? a.endDate * 1000 : Date.now();
  const daysRunning = startMs ? Math.max(1, Math.round((endMs - startMs) / 86400000)) : 0;
  const collationCount = Number(a.collationCount) || 1;

  out.push({ json: {
    adId: a.adArchiveId,
    pageName: snap.pageName || a.pageName || null,
    videoUrl: c.videoHdUrl || c.videoSdUrl,
    thumbnail: c.videoPreviewImageUrl || null,
    body: c.body || snap.body?.text || '',
    headline: c.title || snap.title || '',
    ctaText: c.ctaText || snap.ctaText || null,
    landingUrl: c.linkUrl || snap.linkUrl || null,
    cardCount: cards.length,
    isActive: a.isActive ?? null,
    daysRunning,
    collationCount,
    winScore: daysRunning + collationCount * 5,
  }});
}

return out;

const collect = (o, acc = []) => {
  if (typeof o === 'string') acc.push(o);
  else if (Array.isArray(o)) o.forEach(x => collect(x, acc));
  else if (o && typeof o === 'object') Object.values(o).forEach(x => collect(x, acc));
  return acc;
};

const out = [];

for (const [i, item] of $input.all().entries()) {
  const raw = collect(item.json)
    .filter(s => s.includes('"hook"'))
    .sort((a, b) => b.length - a.length)[0] || '';

  let ai;
  try {
    ai = JSON.parse(raw.replace(/```json|```/g, '').trim());
  } catch (e) {
    ai = {
      error: raw ? 'JSON parse failed' : (item.json.error || 'Gemini text not found'),
      rawSnippet: (raw || JSON.stringify(item.json)).slice(0, 300),
    };
  }

  // NormalizeAds se original data wapas jodo
  let src = {};
  try { src = $('NormalizeAds').itemMatching(i).json; }
  catch (e) { src = $('NormalizeAds').all()[i]?.json || {}; }

  const scores = [ai.hook_strength, ai.audience_relevance, ai.benefit_clarity, ai.cta_quality]
    .map(Number).filter(n => !isNaN(n));
  const creativeScore = scores.length
    ? Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 10) / 10
    : null;

  out.push({ json: {
    adId: src.adId,
    pageName: src.pageName,
    videoUrl: src.videoUrl,
    ctaText: src.ctaText,
    daysRunning: src.daysRunning,
    winScore: src.winScore,
    creativeScore,
    ...ai,
  }});
}

return out;

const W = { longevity: 0.40, hook: 0.20, audience: 0.15, benefit: 0.15, cta: 0.10 };
const MAX_DAYS = 120;
const r1 = n => Math.round(n * 10) / 10;
const ads = JSON.parse(query);
return JSON.stringify(ads.map(a => {
  const p = {
    longevity: r1(Math.min(Number(a.daysRunning) || 0, MAX_DAYS) / MAX_DAYS * 10),
    hook: Number(a.hook_strength) || 0,
    audience: Number(a.audience_relevance) || 0,
    benefit: Number(a.benefit_clarity) || 0,
    cta: Number(a.cta_quality) || 0,
  };
  const finalScore = r1(p.longevity*W.longevity + p.hook*W.hook + p.audience*W.audience + p.benefit*W.benefit + p.cta*W.cta);
  return { adId: a.adId, pillars: p, finalScore };
}));
